import type { Plugin, ResolvedConfig } from 'vite'
import type { MasterCSSVitePluginContext } from '../core'
import { configureBuildDependencyReconciliation, acknowledgeFailedDependencyChange } from '../utils/failed-dependency-reconciliation'
import { closeBuildStylesheetRecovery, prepareBuildStylesheetRecovery, releaseUnstartedBuildStylesheetRecovery } from '../utils/build-watch-recovery'

/** Recover failed watch builds without changing authored files or dependency data. */
export default function BuildStylesheetRecoveryPlugin(context: MasterCSSVitePluginContext): Plugin {
  return {
    name: 'master-css:build-stylesheet-recovery', apply: 'build', enforce: 'pre',
    configResolved(config) {
      if (!config.build?.watch) return
      const createEnvironment = config.build.createEnvironment
      if (!createEnvironment) return
      config.build.createEnvironment = async function (this: ResolvedConfig['build'], name, resolvedConfig) {
        prepareBuildStylesheetRecovery(context, resolvedConfig.cacheDir)
        try {
          const environment = await createEnvironment.call(this, name, resolvedConfig)
          const init = environment.init
          environment.init = async function (this: typeof environment) {
            try { await init.call(this) }
            catch (error) { releaseUnstartedBuildStylesheetRecovery(context);throw error }
          }
          return environment
        } catch (error) {
          releaseUnstartedBuildStylesheetRecovery(context)
          throw error
        }
      }
    },
    buildStart() {
      if (!context.config?.build?.watch) return
      prepareBuildStylesheetRecovery(context, context.config.cacheDir, this.environment ?? context)
      configureBuildDependencyReconciliation(context, context.config.build.watch)
    },
    watchChange(id) { acknowledgeFailedDependencyChange(context, id) },
    closeWatcher() { closeBuildStylesheetRecovery(context, this.environment ?? context) }
  }
}

